#include <cuda_runtime.h>
#include <vector>
#include <cstdio>
#include "linear-float-kernel.cuh"
#define CHECK(x) do{if((x)!=cudaSuccess)return 2;}while(0)
int main(){const int records=32771,n=records+4;std::vector<int> indices(n);for(int i=0;i<n;i++)indices[i]=i-2;int*ix;CHECK(cudaMalloc(&ix,n*4));CHECK(cudaMemcpy(ix,indices.data(),n*4,cudaMemcpyHostToDevice));float *input[3],*output[3];cudaTextureObject_t tex[3];for(int j=0;j<3;j++){int components=1<<j;std::vector<float> data(records*components);for(int i=0;i<data.size();i++)data[i]=float((i*37%65521)-32760)/128.0f;CHECK(cudaMalloc(&input[j],data.size()*4));CHECK(cudaMalloc(&output[j],n*components*4));CHECK(cudaMemcpy(input[j],data.data(),data.size()*4,cudaMemcpyHostToDevice));cudaResourceDesc r={};r.resType=cudaResourceTypeLinear;r.res.linear.devPtr=input[j];r.res.linear.sizeInBytes=data.size()*4;r.res.linear.desc=j==0?cudaCreateChannelDesc<float>():j==1?cudaCreateChannelDesc<float2>():cudaCreateChannelDesc<float4>();cudaTextureDesc d={};d.readMode=cudaReadModeElementType;CHECK(cudaCreateTextureObject(&tex[j],&r,&d,nullptr));char path[100];sprintf(path,"reports/linear-float-input-%d.bin",components);FILE*f=fopen(path,"wb");if(!f)return 2;fwrite(data.data(),4,data.size(),f);fclose(f);}
fetchFloatLinear<<<(n+127)/128,128>>>(tex[0],tex[1],tex[2],ix,output[0],(float2*)output[1],(float4*)output[2],n);for(int j=0;j<3;j++){int components=1<<j;std::vector<float> result(n*components);CHECK(cudaMemcpy(result.data(),output[j],result.size()*4,cudaMemcpyDeviceToHost));char path[100];sprintf(path,"reports/linear-float-native-%d.bin",components);FILE*f=fopen(path,"wb");if(!f)return 2;fwrite(result.data(),4,result.size(),f);fclose(f);CHECK(cudaDestroyTextureObject(tex[j]));CHECK(cudaFree(input[j]));CHECK(cudaFree(output[j]));}CHECK(cudaFree(ix));printf("Captured %d lookups of float, float2 and float4 linear textures.\n",n);}
